import { z } from 'zod';

/** A pix charge for a held booking, as the player's payment screen needs it. */
export const paymentChargeSchema = z.object({
  chargeId: z.string().min(1),
  method: z.literal('pix'),
  /** The QR code, ready to inline (generated by the server, no external data). */
  qrCodeSvg: z.string().min(1),
  /** The "pix copia e cola" text. */
  copyPaste: z.string().min(1),
  expiresAt: z.iso.datetime({ offset: true }),
  /** True only with the fake provider: the "Simular pagamento" button exists. */
  simulatable: z.boolean(),
});
export type PaymentCharge = z.infer<typeof paymentChargeSchema>;

/** Answer of the (fake) payment webhook. Never carries booking details. */
export const paymentResultSchema = z.object({
  status: z.literal('confirmed'),
});
export type PaymentResult = z.infer<typeof paymentResultSchema>;
